class Solution {
    public String addBinary(String a, String b) {
        String ans=new String();
        int i=a.length()-1;
        int j=b.length()-1;
        int carry=0;
        while(i>=0 || j>=0 || carry==1){
            int add=carry;
            if(i>=0) add+=a.charAt(i)-'0';
            if(j>=0) add+=b.charAt(j)-'0';
            ans=(char)(add%2)+ans;
            carry=add/2;
            i--;
            j--;
        }
        return ans;    
